# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Metric-closure relay arborescence broadcast.

    Computes all-pairs shortest paths over h restricted to {src} ∪ dsts,
    builds a metric-closure digraph C whose edge weights are pairwise
    shortest-path costs, then computes a minimum-cost directed arborescence
    rooted at src on C. Each destination's delivery chain is the
    concatenation of closure-edge paths from src along the arborescence,
    permitting cheap dst→dst relay hops instead of forcing all traffic
    through src's egress. Every (dst, partition) receives a contiguous
    src→dst edge chain in G. Falls back to per-destination Dijkstra on any
    exception.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    def emit(dst, pairs):
        for s, t in pairs:
            for j in range(bc_topology.num_partitions):
                bc_topology.append_dst_partition_path(dst, j, [s, t, G[s][t]])

    def dijkstra_pairs(dst):
        p = nx.dijkstra_path(h, src, dst, weight="cost")
        return [(p[i], p[i + 1]) for i in range(len(p) - 1)]

    routes = None
    try:
        """Dual-ascent Steiner with Takahashi-Matsuyama SPH primal.

        Phase 1 (dual ascent, Wong/cut-dual): maintain reduced costs
        rc = c - sum(raised cut duals); raise a dual per unreached terminal
        on the min-reduced-cost directed cut out of the tight-edge-reachable
        set S grown from src over zero-reduced-cost edges; yields the
        tight-edge subgraph (candidate A) and a dual lower bound.
        Phase 2 (SPH primal, candidate B): grow a tree from src by repeatedly
        connecting the nearest remaining terminal via a multi-source Dijkstra
        on the reverse graph (cheapest path from the current tree into that
        terminal), merging shared prefixes — the classic best primal for
        directed Steiner.
        Phase 3 (bounding): also build candidate C, the union of per-dst
        full-graph Dijkstra paths pruned by reverse edge deletion. Evaluate
        all three by true shared-edge cost (each unique edge paid once) and
        emit per-dst Dijkstra chains on the cheapest. Candidate C is bounded
        by the per-dst Dijkstra total, so total cost cannot regress; SPH
        captures shared-prefix savings. Deterministic, sub-second, no solver.
        """
        import numpy as np

        edges = list(h.edges())
        nE = len(edges)
        eidx = {e: i for i, e in enumerate(edges)}
        costs = np.array([
            float(h[u][v]["cost"]) if h[u][v].get("cost") is not None else 1e6
            for u, v in edges
        ], dtype=float)

        reach = [d for d in dsts if d != src and nx.has_path(h, src, d)]
        if not reach:
            raise ValueError("no reachable dsts")

        # ---------- Phase 1: dual ascent ----------
        out_idx = {v: [eidx[e] for e in h.out_edges(v)] for v in h.nodes()}
        rc = costs.copy()
        EPS = 1e-9

        def grow():
            seen = {src}
            stack = [src]
            while stack:
                v = stack.pop()
                for i in out_idx[v]:
                    u = edges[i][1]
                    if u not in seen and rc[i] <= EPS:
                        seen.add(u)
                        stack.append(u)
            return seen

        S = grow()
        unreached = set(reach) - S
        rounds = 0
        while unreached and rounds <= len(reach) + nE:
            rounds += 1
            for d in sorted(unreached):
                cut = [i for v in S for i in out_idx[v] if edges[i][1] not in S]
                if not cut:
                    raise RuntimeError("terminal unreachable in cut dual")
                delta = min(rc[i] for i in cut)
                if delta <= EPS:
                    best = min(cut, key=lambda i: rc[i])
                    rc[best] = 0.0
                    continue
                for i in cut:
                    rc[i] -= delta
            S = grow()
            unreached = set(reach) - S
        if unreached:
            raise RuntimeError("dual ascent failed to reach all terminals")

        subA = nx.DiGraph()
        subA.add_nodes_from(h.nodes())
        tight = rc <= EPS
        for i, (u, v) in enumerate(edges):
            if tight[i]:
                subA.add_edge(u, v, **h[u][v])
        fwd = set(nx.descendants(subA, src)) | {src}
        subA_rev = subA.reverse(copy=False)
        rev = {src}
        for d in reach:
            rev |= nx.descendants(subA_rev, d)
        for u, v in list(subA.edges()):
            if u not in fwd or v not in rev:
                subA.remove_edge(u, v)

        # ---------- Phase 2: Takahashi-Matsuyama SPH tree ----------
        subB = nx.DiGraph()
        subB.add_nodes_from(h.nodes())
        h_rev = h.reverse(copy=False)
        tree_nodes = {src}
        remaining = set(reach)
        while remaining:
            dist, _ = nx.multi_source_dijkstra(h_rev, tree_nodes, weight="cost")
            cand = [(dist[d], d) for d in remaining if d in dist]
            if not cand:
                raise RuntimeError("SPH could not connect a terminal")
            _, d = min(cand)
            _, path_rev = nx.multi_source_dijkstra(h_rev, tree_nodes, d, weight="cost")
            p = list(reversed(path_rev))
            for i in range(len(p) - 1):
                subB.add_edge(p[i], p[i + 1], **h[p[i]][p[i + 1]])
            tree_nodes.update(p)
            remaining.discard(d)

        # ---------- Phase 3: pruned union-Dijkstra candidate ----------
        subC = nx.DiGraph()
        subC.add_nodes_from(h.nodes())
        for d in reach:
            p = nx.dijkstra_path(h, src, d, weight="cost")
            for i in range(len(p) - 1):
                subC.add_edge(p[i], p[i + 1], **h[p[i]][p[i + 1]])
        for u, v in sorted(
            subC.edges(),
            key=lambda e: -float(
                subC[e[0]][e[1]]["cost"]
                if subC[e[0]][e[1]].get("cost") is not None else 1e6
            ),
        ):
            subC.remove_edge(u, v)
            if not all(nx.has_path(subC, src, d) for d in reach):
                subC.add_edge(u, v, **h[u][v])

        def tree_cost(sub):
            used = set()
            for d in reach:
                try:
                    p = nx.dijkstra_path(sub, src, d, weight="cost")
                except Exception:
                    return float("inf")
                for i in range(len(p) - 1):
                    used.add((p[i], p[i + 1]))
            return sum(
                float(sub[u][v]["cost"]) if sub[u][v].get("cost") is not None else 1e6
                for u, v in used
            )

        best_sub = min((subA, subB, subC), key=tree_cost)

        routes = {}
        for dst in dsts:
            try:
                p = nx.dijkstra_path(best_sub, src, dst, weight="cost")
                routes[dst] = [(p[i], p[i + 1]) for i in range(len(p) - 1)]
            except Exception:
                routes[dst] = dijkstra_pairs(dst)
    except Exception:
        routes = None

    if routes is None:
        for dst in dsts:
            emit(dst, dijkstra_pairs(dst))
        return bc_topology

    for dst in dsts:
        emit(dst, routes[dst])

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)
